-- Source: FED_SEC_13F_HOLDINGS (101261252 rows)
-- Generated by scripts/gen_mart_models.py
--
-- Materialized as a VIEW: this is a straight passthrough of a 101,261,252-row
-- landing table, so a physical copy would pay twice for the same bytes without
-- precomputing any join, filter, or aggregation.

with source as (
    select * from {{ source('ripple_raw', 'FED_SEC_13F_HOLDINGS') }}
)

select
    ACCESSION_NUMBER as accession_number,
    INFOTABLE_SK as infotable_sk,
    NAMEOFISSUER as nameofissuer,
    TITLEOFCLASS as titleofclass,
    CUSIP as cusip,
    FIGI as figi,
    "VALUE" as value_col,
    -- VALUE mixes two units across eras (pattern sweep 2026-07-27, confirmed
    -- live 2026-08-22): legacy quarterly files (2013q2-2022q3, named
    -- YYYYqN_form13f.zip) report THOUSANDS of dollars; modern files (2024+,
    -- named ddmmmyyyy-ddmmmyyyy_form13f.zip) report WHOLE dollars (SEC rule
    -- change, Jan 2023). Per-file medians split ~500-1,200 vs ~300k-460k — an
    -- exact 1000x unit gap. value_usd is every era in whole dollars; never sum
    -- value_col across eras. Files for 2021q3-2023q4 are absent entirely
    -- (coverage hole, tracked separately).
    iff(_SRC_FILE rlike '20[0-9][0-9]q[1-4]_form13f\\.zip', 'thousands', 'dollars')
        as value_unit,
    try_to_double("VALUE")
      * iff(_SRC_FILE rlike '20[0-9][0-9]q[1-4]_form13f\\.zip', 1000, 1)
        as value_usd,
    try_to_double(SSHPRNAMT) as sshprnamt,
    SSHPRNAMTTYPE as sshprnamttype,
    PUTCALL as putcall,
    INVESTMENTDISCRETION as investmentdiscretion,
    OTHERMANAGER as othermanager,
    VOTING_AUTH_SOLE as voting_auth_sole,
    VOTING_AUTH_SHARED as voting_auth_shared,
    VOTING_AUTH_NONE as voting_auth_none,
    _SRC_FILE as src_file
from source
